<!doctype html>
<html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#17252b;font-size:12px}h1{font-size:22px;margin-bottom:4px}.header{border-bottom:2px solid #0c7772;padding-bottom:12px;margin-bottom:20px}.row{padding:8px 0;border-bottom:1px solid #d8e0df}.label{color:#667579;display:inline-block;width:150px}.total{font-size:16px;font-weight:bold;margin-top:20px}</style></head><body><div class="header"><h1>MediCore Hospital</h1><div>Official payment receipt</div></div><div class="row"><span class="label">Receipt number</span>RCT-{{ str_pad((string) $payment->id, 6, '0', STR_PAD_LEFT) }}</div><div class="row"><span class="label">Date</span>{{ $payment->paid_at?->format('d M Y, H:i') }}</div><div class="row"><span class="label">Patient</span>{{ $payment->invoice?->patient?->first_name }} {{ $payment->invoice?->patient?->last_name }}</div><div class="row"><span class="label">Patient ID</span>{{ $payment->invoice?->patient?->patient_number }}</div><div class="row"><span class="label">Invoice</span>{{ $payment->invoice?->invoice_number }}</div><div class="row"><span class="label">Payment method</span>{{ str_replace('_', ' ', ucfirst($payment->payment_method)) }}</div><div class="row"><span class="label">Reference</span>{{ $payment->reference ?: 'N/A' }}</div><div class="total">Amount paid: TZS {{ number_format($payment->amount, 2) }}</div></body></html>